"packages/studio-panel/vendor\",\n    \"vendor/dsh-dog/package.json\",\n    \"vendor/dsh-dog/lib\",\n    \"vendor/dsh-dog/schemas\",\n    \"vendor/dsh-dog/LICENSE\",\n    \"vendor/dsh-dog/UPSTREAM.md\",\n    \"presets/openwrite\",\n    \"release/*.json\",\n    \"release/*.lock\",\n    \"release/*.whl\",\n    \"scripts/prepare.mjs\",\n    \"README.md\",\n    \"LICENSE\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"dog-tools.mjs\",\n    \"packages/openwrite-bridge/lib\",\n    \"packages/openwrite-bridge/package.json\",\n    \"packages/studio-panel/lib\",\n    \"packages/studio-panel/package.json\",\n    \"scripts/dog\",\n    \"scripts/maintenance.mjs\",\n    \"scripts/safe-upgrade.mjs\",\n    \"packages/openwrite-bridge/LICENSE\",\n    \"packages/studio-panel/LICENSE\",\n    \"release/licenses\",\n    \"release/wheels\",\n    \"release/*.in\",\n    \"docs\",\n    \"assets\"\n  ],\n  \"dependencies\": {\n    \"@deepseek-ai/schemastery\": \"3.18.2\",\n    \"ajv\": \"^8.20.0\",\n    \"ajv-formats\": \"^3.0.1\",\n    \"fflate\": \"0.8.2\",\n    \"proper-lockfile\": \"4.1.2\",\n    \"tar\": \"7.5.7\",\n    \"js-yaml\": \"4.3.1\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.2 || ~4.0.4\",\n    \"@deepseek-ai/dsh-home-paths\": \"0.1.2-rc.1 || 0.1.5-alpha.1 || 0.2.0-rc.2 || 0.2.1-rc.2 || 0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-settings\": \"0.1.2-rc.1 || 0.1.5-alpha.1 || 0.2.0-rc.2 || 0.2.1-rc.2 || 0.2.1-rc.3\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.2-rc.1 || 0.1.5-alpha.1 || 0.2.0-rc.2 || 0.2.1-rc.2 || 0.2.1-rc.3\"\n  },\n  \"bin\": {\n    \"openwrite-maintenance\": \"scripts/maintenance.mjs\",\n    \"openwrite-safe-upgrade\": \"scripts/safe-upgrade.mjs\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/LiPu-jpg/Openwrite.git\"\n  },\n  \"homepage\": \"https://github.com/LiPu-jpg/Openwrite#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/LiPu-jpg/Openwrite/issues\"\n  },\n  \"os\": [\n    \"darwin\",\n   